    ssrLevels_en: ['Increases Attack by 50%.', 'ATK boost increases to 60%.', 'Divine Blessing: the artifact bearer gains an additional 10% Crit Rate.', 'ATK boost increases to 70%.', 'Blessing: the artifact bearer gains an additional 10% Crit Damage.'],
